"""Inspect existing node files without repairing or modifying them."""
import argparse
import json
import os
from pathlib import Path
import re


JOB_SUFFIX = re.compile(r'(.*)_[0-9a-fA-F]{8}')


class JsonNumber:
    """Retain a parser-validated number token without floating-point loss."""

    def __init__(self, token):
        self.token = token


def reject_constant(value):
    raise ValueError('Invalid JSON constant: ' + value)


def read_object(path):
    try:
        with path.open('r', encoding='utf-8') as stream:
            value = json.load(stream, parse_float=JsonNumber,
                              parse_constant=reject_constant)
    except (OSError, ValueError, RecursionError):
        return None
    return value if isinstance(value, dict) else None


def encode_json(value):
    # Only json.load's numeric callback creates these validated raw tokens.
    # Preserve them at every nesting level instead of converting to float.
    if isinstance(value, JsonNumber):
        return value.token
    if isinstance(value, dict):
        return '{' + ','.join(
            json.dumps(key, ensure_ascii=True) + ':' + encode_json(item)
            for key, item in value.items()) + '}'
    if isinstance(value, list):
        return '[' + ','.join(encode_json(item) for item in value) + ']'
    return json.dumps(value, ensure_ascii=True, separators=(',', ':'),
                      allow_nan=False)


def directories(path):
    try:
        return sorted((p for p in path.iterdir() if p.is_dir()),
                      key=lambda p: p.name)
    except OSError:
        return []


def diagnose(node):
    pending = []
    halted = []
    inflight = []

    for budget in directories(node / 'llmcall'):
        for call in directories(budget):
            if read_object(call / 'request.json') is None:
                continue
            # Receipt and raw are presence markers; never parse either file.
            if os.path.lexists(call / 'receipt.json'):
                continue
            stage = 'raw' if os.path.lexists(call / 'raw.json') else 'request'
            pending.append({'budget': budget.name, 'call_id': call.name,
                            'stage': stage})

    for job in directories(node / 'jobs'):
        match = JOB_SUFFIX.fullmatch(job.name)
        if match is None:
            continue
        rid = match.group(1)
        if not (node / 'author' / 'req' / rid).is_dir():
            continue
        frame = read_object(job / 'frame.json')
        if frame is None or frame.get('phase') != 'halted':
            continue
        halt = frame.get('halt')
        if not isinstance(halt, dict):
            halt = {}
        halted.append({'job': job.name, 'rid': rid,
                       'kind': halt.get('kind'), 'why': halt.get('why')})

    for budget in directories(node / 'budget'):
        ledger = read_object(budget / 'ledger.json')
        if ledger is None:
            continue
        count = ledger.get('inflight')
        if type(count) is int and count > 0:
            inflight.append({'budget': budget.name, 'inflight': count})

    pending.sort(key=lambda row: (row['budget'], row['call_id'], row['stage']))
    halted.sort(key=lambda row: row['job'])
    inflight.sort(key=lambda row: row['budget'])
    return {'v': 1, 'llmcall_pending': pending, 'author_halted': halted,
            'budget_inflight': inflight}


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('node', type=Path)
    args = parser.parse_args(argv)
    if not args.node.is_dir():
        parser.error('node must be an existing directory')
    print(encode_json(diagnose(args.node)))
    return 0
